import 'dart:ffi' as ffi;

import 'package:ffi/ffi.dart';

import '../g/apriltag.g.dart' as C;
import 'base.dart';

enum FamilyType {
  tag16h5('tag16h5'),
  tag25h9('tag25h9'),
  tag36h10('tag36h10'),
  tag36h11('tag36h11'),
  tagCircle21h7('tagCircle21h7'),
  tagCircle49h12('tagCircle49h12'),
  tagCustom48h12('tagCustom48h12'),
  tagStandard41h12('tagStandard41h12'),
  tagStandard52h13('tagStandard52h13'),
  tagUserDefined('tagUserDefined'),
  unknown('unknown'),
  ;

  final String name;
  const FamilyType(this.name);

  factory FamilyType.fromName(String name) => switch (name) {
    'tag16h5' => FamilyType.tag16h5,
    'tag25h9' => FamilyType.tag25h9,
    'tag36h10' => FamilyType.tag36h10,
    'tag36h11' => FamilyType.tag36h11,
    'tagCircle21h7' => FamilyType.tagCircle21h7,
    'tagCircle49h12' => FamilyType.tagCircle49h12,
    'tagCustom48h12' => FamilyType.tagCustom48h12,
    'tagStandard41h12' => FamilyType.tagStandard41h12,
    'tagStandard52h13' => FamilyType.tagStandard52h13,
    'tagUserDefined' => FamilyType.tagUserDefined,
    _ => FamilyType.unknown,
  };
}

class AprilTagFamily extends NativeObject<C.apriltag_family_t> {
  static final _finalizer = ffi.NativeFinalizer(calloc.nativeFree);
  final FamilyType type;
  AprilTagFamily.fromPointer(
    ffi.Pointer<C.apriltag_family_t> ptr, {
    this.type = FamilyType.unknown,
    super.attach,
    super.externalSize,
  }) : super(ptr.cast());

  /// Represents a tag family. Every tag belongs to a tag family. Tag
  /// families are generated by the Java tool
  /// april.tag.TagFamilyGenerator and can be converted to C using
  /// april.tag.TagToC.
  ///
  /// - codes: The codes in the family.
  /// - bitX: The bit locations in the X direction.
  /// - bitY: The bit locations in the Y direction.
  /// - h: The minimum hamming distance between any two codes.
  /// - name: A human-readable name, e.g., "tag36h11".
  factory AprilTagFamily.custom(
    List<int> codes,
    int widthAtBorder,
    int totalWidth,
    bool reversedBorder,
    List<int> bitX,
    List<int> bitY,
    int h,
    String name,
  ) {
    final pCodes = calloc<ffi.Uint64>(codes.length)..asTypedList(codes.length).setAll(0, codes);
    final pBitX = calloc<ffi.Uint32>(bitX.length)..asTypedList(bitX.length).setAll(0, bitX);
    final pBitY = calloc<ffi.Uint32>(bitY.length)..asTypedList(bitY.length).setAll(0, bitY);
    final cName = name.toNativeUtf8().cast<ffi.Char>();
    final p = calloc<C.apriltag_family_t>()
      ..ref.ncodes = codes.length
      ..ref.codes = pCodes
      ..ref.width_at_border = widthAtBorder
      ..ref.total_width = totalWidth
      ..ref.reversed_border = reversedBorder
      ..ref.nbits = bitX.length
      ..ref.bit_x = pBitX
      ..ref.bit_y = pBitY
      ..ref.h = h
      ..ref.name = cName;
    final rval = AprilTagFamily.fromPointer(
      p,
      type: FamilyType.tagUserDefined,
      externalSize: ffi.sizeOf<C.apriltag_family_t>(),
    );
    _finalizer.attach(rval, pCodes.cast());
    _finalizer.attach(rval, pBitX.cast());
    _finalizer.attach(rval, pBitY.cast());
    _finalizer.attach(rval, cName.cast());
    return rval;
  }

  factory AprilTagFamily.predefined(String name) {
    return switch (name) {
      "tag16h5" => AprilTagFamily.tag16h5(),
      "tag25h9" => AprilTagFamily.tag25h9(),
      "tag36h10" => AprilTagFamily.tag36h10(),
      "tag36h11" => AprilTagFamily.tag36h11(),
      "tagCircle21h7" => AprilTagFamily.tagCircle21h7(),
      "tagCircle49h12" => AprilTagFamily.tagCircle49h12(),
      "tagCustom48h12" => AprilTagFamily.tagCustom48h12(),
      "tagStandard41h12" => AprilTagFamily.tagStandard41h12(),
      "tagStandard52h13" => AprilTagFamily.tagStandard52h13(),
      _ => throw ArgumentError.value(name, "name", "Unknown tag family name"),
    };
  }

  factory AprilTagFamily.tag16h5() {
    return AprilTagFamily.fromPointer(C.tag16h5_create(), type: FamilyType.tag16h5);
  }

  factory AprilTagFamily.tag25h9() {
    return AprilTagFamily.fromPointer(C.tag25h9_create(), type: FamilyType.tag25h9);
  }

  factory AprilTagFamily.tag36h10() {
    return AprilTagFamily.fromPointer(C.tag36h10_create(), type: FamilyType.tag36h10);
  }

  factory AprilTagFamily.tag36h11() {
    return AprilTagFamily.fromPointer(C.tag36h11_create(), type: FamilyType.tag36h11);
  }

  factory AprilTagFamily.tagCircle21h7() {
    return AprilTagFamily.fromPointer(C.tagCircle21h7_create(), type: FamilyType.tagCircle21h7);
  }

  factory AprilTagFamily.tagCircle49h12() {
    return AprilTagFamily.fromPointer(C.tagCircle49h12_create(), type: FamilyType.tagCircle49h12);
  }

  factory AprilTagFamily.tagCustom48h12() {
    return AprilTagFamily.fromPointer(C.tagCustom48h12_create(), type: FamilyType.tagCustom48h12);
  }

  factory AprilTagFamily.tagStandard41h12() {
    return AprilTagFamily.fromPointer(C.tagStandard41h12_create(), type: FamilyType.tagStandard41h12);
  }

  factory AprilTagFamily.tagStandard52h13() {
    return AprilTagFamily.fromPointer(C.tagStandard52h13_create(), type: FamilyType.tagStandard52h13);
  }

  C.apriltag_family_t get ref => ptr.ref;

  List<int> get codes => ref.codes.asTypedList(ref.ncodes);
  int get widthAtBorder => ref.width_at_border;
  int get totalWidth => ref.total_width;
  bool get reversedBorder => ref.reversed_border;
  int get nbits => ref.nbits;
  List<int> get bitX => ref.bit_x.asTypedList(ref.nbits);
  List<int> get bitY => ref.bit_y.asTypedList(ref.nbits);
  int get h => ref.h;
  String get name => ref.name.cast<Utf8>().toDartString();

  @override
  ffi.NativeFinalizer get finalizer => _finalizer;

  @override
  List<Object?> get props => [ptr.address];

  @override
  void release() {
    for (final p in [ref.bit_x, ref.bit_y, ref.name, ref.impl, ptr]) {
      if (p != ffi.nullptr) {
        calloc.free(p);
      }
    }
  }
}
